python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/output/result.xlsx'
wb=load_workbook(path)
ws=wb['Task']
# Step 1 lookup formulas in H:L for row blocks
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        for c in range(8,13):
            col=get_column_letter(c)
            ws.cell(r,c).value = f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
# Step 2 net production slack
for r in range(35,41):
    f_row = r - 23   # 35->12
    s_row = r - 16   # 35->19
    cap_row = r - 9  # 35->26
    for c in range(8,13):
        col=get_column_letter(c)
        ws.cell(r,c).value = f'=({col}{f_row}-{col}{s_row})/{col}{cap_row}*100'
# Statistics based on labels rows 42-47
for r in range(42,48):
    for c in range(8,13):
        col=get_column_letter(c)
        if r == 42:
            formula = f'=MIN({col}$35:{col}$40)'
        elif r == 43:
            formula = f'=MAX({col}$35:{col}$40)'
        elif r == 44:
            formula = f'=MEDIAN({col}$35:{col}$40)'
        elif r == 45:
            formula = f'=AVERAGE({col}$35:{col}$40)'
        elif r == 46:
            formula = f'=PERCENTILE.INC({col}$35:{col}$40,0.25)'
        elif r == 47:
            formula = f'=PERCENTILE.INC({col}$35:{col}$40,0.75)'
        ws.cell(r,c).value = formula
# Step 3 weighted mean
for c in range(8,13):
    col=get_column_letter(c)
    ws.cell(50,c).value = f'=SUMPRODUCT({col}$35:{col}$40,{col}$26:{col}$31)/SUM({col}$26:{col}$31)'
# request recalculation on open
try:
    wb.calculation.fullCalcOnLoad = True
    wb.calculation.forceFullCalc = True
    wb.calculation.calcMode = 'auto'
except Exception as e:
    print('calc property warning:', e)
wb.save(path)
print('Saved formulas to', path)
# print representative formulas
for addr in ['H12','L17','H19','L24','H26','L31','H35','L40','H42','H43','H44','H45','H46','H47','H50','L50']:
    print(addr, ws[addr].value)
